const FileOpenError = error{
    AccessDenied,
    OutOfMemory,
    FileNotFound,
};

const Tag = enum { circle, square, triangle };
const Shape = union(Tag) {
    circle: f32,
    square: f32,
    triangle: struct { base: f32, height: f32 },
};

test "array equality" {
    const expected = [_]i32{ 1, 2, 3 };
    const actual = [_]i32{ 1, 2, 3 };
    try std.testing.expectEqualSlices(i32, &expected, &actual);
}

fn readFile(path: []const u8, allocator: std.mem.Allocator) ![]u8 {
    const file = try std.fs.cwd().openFile(path, .{});
    defer file.close();
    return try file.readToEndAlloc(allocator, 1024 * 1024);
}

pub fn List(comptime T: type) type {
    return struct {
        items: []T,
        capacity: usize,

        pub fn init(allocator: std.mem.Allocator) !@This() {
            return .{ .items = &.{}, .capacity = 0 };
        }
    };
}

test "detect memory leak with GPA" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer {
        const deinit_status = gpa.deinit();
        if (deinit_status == .leak) @panic("Memory leak detected!");
    }
    const allocator = gpa.allocator();
    const bytes = try allocator.alloc(u8, 100);
    allocator.free(bytes);
}

pub const Vector2 = struct {
    x: f32,
    y: f32,
    pub fn add(self: Vector2, other: Vector2) Vector2 {
        return .{ .x = self.x + other.x, .y = self.y + other.y };
    }
    pub fn dot(self: Vector2, other: Vector2) f32 {
        return self.x * other.x + self.y * other.y;
    }
};

var mutex = std.Thread.Mutex{};
var shared_val: i32 = 0;

fn increment() void {
    mutex.lock();
    defer mutex.unlock();
    shared_val += 1;
}

const SliceWindow = struct {
    ptr: [*]const u8,
    len: usize,
    pub fn sub(self: SliceWindow, start: usize, end: usize) !SliceWindow {
        if (end > self.len or start > end) return error.OutOfBounds;
        return .{ .ptr = self.ptr + start, .len = end - start };
    }
};
